cypress_script:
describe('Login Form', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('input[id="username"]').type('tomsmith');
    cy.get('input[id="password"]').type('SuperSecretPassword!');
    cy.get('button[class="radius"]').click();
    cy.url().should('not.eq', 'https://the-internet.herokuapp.com/login');
  });
  it('should not log in with empty credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('button[class="radius"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
    cy.get('div[id="flash-messages"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Form', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('input[id="username"]', 'tomsmith');
    await page.fill('input[id="password"]', 'SuperSecretPassword!');
    await page.click('button[class="radius"]');
    await expect(page).toHaveURL(/^(?!.*login).*/);
  });
  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.click('button[class="radius"]');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/login');
    await expect(page.locator('div[id="flash-messages"]').isVisible()).toBeTruthy();
  });
});
